namespace I76.Formats.Shell;

/// <summary>
/// database.tvf (Nitro Pack) against DATABASE.MW2 (docs/nitro-survey.md d1). Nitro renumbered the records (76 against 83): 55 are
/// byte-identical at shifted numbers, the rest are new or redrawn. The shell is written in base numbers; this maps each to
/// the Nitro record, and each base bank's sprite numbers to the sprite in the Nitro bank with the same picture.
/// The tables are generated by `i76 --install BASE nitro-map NITRO_DIR` (tools/I76.Cli) by content: records by their bytes,
/// sprites by their size and pixels. What changed for good is paired by hand there (the backgrounds, which were looked at
/// side by side) or by nearest size (redrawn panels inside a bank).
/// </summary>
public static partial class NitroShellMap
{
    public const int NitroCount = 76;

    /// <summary>The Nitro record for base record <paramref name="id"/> (1..83), 0 when Nitro has none.</summary>
    public static int Record(int id) => id >= 1 && id < Records.Length ? Records[id] : 0;

    /// <summary>For base bank <paramref name="id"/>: for each base sprite number the Nitro bank's, −1 when it has none. Null if the bank maps one to one.</summary>
    public static int[]? SpriteMap(int id) => Sprites.TryGetValue(id, out var m) ? m : null;

    /// <summary>
    /// Nitro backgrounds that are not byte-identical to any base record (new or redrawn: main menu 22, scenario form 21,
    /// standings 23–25, the network screens 14–19, control configuration 12, parts catalog 2, a Joe's pad 7), by
    /// comparing database.tvf with DATABASE.MW2 (`i76 bg`). A base upscale must not stand in for these.
    /// </summary>
    public static bool Redrawn(int nitroRecord) => nitroRecord is 2 or 7 or 12 or (>= 14 and <= 19) or (>= 21 and <= 25);
}
